import{_ as e,o as d,c as o,a3 as r}from"./chunks/framework.DAK02U1-.js";const b=JSON.parse('{"title":"Handler 协议","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Handler 协议 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/handler-protocol"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/handler-protocol"}]]},"headers":[],"relativePath":"zh/catter/design/handler-protocol.md","filePath":"zh/catter/design/handler-protocol.md","lastUpdated":1792896246000}'),a={name:"zh/catter/design/handler-protocol.md"};function c(n,t,l,i,h,s){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="handler-协议" tabindex="-1">Handler 协议 <a class="header-anchor" href="#handler-协议" aria-label="Permalink to &quot;Handler 协议&quot;">​</a></h1><p>本文规定 catter 与 <a href="./../scripting/handlers">handler</a> 之间的协议，供不借助 SDK 编写 handler 时参考。各 SDK 都实现了该协议，其类型与 catter 的类型生成自同一份定义。</p><h2 id="传输" tabindex="-1">传输 <a class="header-anchor" href="#传输" aria-label="Permalink to &quot;传输&quot;">​</a></h2><p>消息采用 <a href="https://www.jsonrpc.org/specification" target="_blank" rel="noreferrer">JSON-RPC 2.0</a>，按 Language Server Protocol 的方式分帧：一个 <code>Content-Length: &lt;n&gt;</code> 头部、一个空行（<code>\\r\\n\\r\\n</code>），然后是 <code>n</code> 字节的 UTF-8 JSON。</p><ul><li>由 catter 启动的 handler（<code>--handler</code>）从 stdin 读取 catter 的消息，把自己的消息写到 stdout。它的 stderr 就是终端的 stderr。</li><li>监听端口的 handler（<code>--connect</code>）在每个 TCP 连接上做同样的事：一个连接就是一个会话。</li></ul><p>catter 发送请求和通知；handler 只应答请求，不发送其他任何消息。除下文的消息外，catter 还可能像 Language Server Protocol 那样，为它不再等待的请求发送 <code>$/cancelRequest</code>：handler 可以忽略它。</p><h2 id="一次会话" tabindex="-1">一次会话 <a class="header-anchor" href="#一次会话" aria-label="Permalink to &quot;一次会话&quot;">​</a></h2><ol><li><code>initialize</code>（请求）：会话开始。handler 在应答中声明它想收到哪些消息。</li><li>构建运行期间，针对每条命令：<code>command</code>，对做决定的 handler 是请求，对不做决定的 handler 是通知；catter 未能捕获某条命令时发送 <code>error</code>；命令运行完毕后发送 <code>exit</code>。只有 handler 要求过的通知才会发来。</li><li><code>finish</code>（请求）：构建已结束。handler 应答后，catter 结束它的输入：由 catter 启动的 handler 随即退出；通过 TCP 连接时，catter 关闭自己一侧的连接，由 handler 关闭连接。</li></ol><p>并行构建中的命令会相互重叠：多个 <code>command</code> 请求可以同时等待应答，handler 按请求的 id 应答，顺序不限。</p><h2 id="消息" tabindex="-1">消息 <a class="header-anchor" href="#消息" aria-label="Permalink to &quot;消息&quot;">​</a></h2><h3 id="initialize" tabindex="-1"><code>initialize</code> <a class="header-anchor" href="#initialize" aria-label="Permalink to &quot;`initialize`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>整数</td><td>协议版本：<code>1</code>。</td></tr><tr><td><code>session</code></td><td>字符串</td><td>区分同一个 handler 通过 TCP 服务的多个会话。</td></tr><tr><td><code>mode</code></td><td>字符串</td><td>命令的捕获方式：<code>inject</code> 或 <code>replay</code>。</td></tr><tr><td><code>build.command</code></td><td>OS 字符串数组</td><td>构建命令。</td></tr><tr><td><code>build.cwd</code></td><td>OS 字符串</td><td>它的工作目录。</td></tr></tbody></table><p>结果：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>decides</code></td><td>布尔值</td><td>每条命令都以请求的形式发来，构建会等待它的应答。</td></tr><tr><td><code>events.command</code></td><td>布尔值</td><td>不做决定的 handler 会收到每条命令的通知。</td></tr><tr><td><code>events.error</code></td><td>布尔值</td><td>handler 会收到 catter 未能捕获的命令的通知。</td></tr><tr><td><code>events.exit</code></td><td>布尔值</td><td>handler 会收到每条命令退出的通知。</td></tr><tr><td><code>env</code></td><td>布尔值</td><td>命令携带它的环境变量。</td></tr></tbody></table><h3 id="command" tabindex="-1"><code>command</code> <a class="header-anchor" href="#command" aria-label="Permalink to &quot;`command`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>整数</td><td>命令在会话中的 id。</td></tr><tr><td><code>parent</code></td><td>整数，可选</td><td>启动它的命令；构建命令没有此字段。</td></tr><tr><td><code>cwd</code></td><td>OS 字符串</td><td>它的工作目录。</td></tr><tr><td><code>executable</code></td><td>OS 字符串</td><td>它运行的程序。</td></tr><tr><td><code>args</code></td><td>OS 字符串数组</td><td>它的参数，第一个是程序名。</td></tr><tr><td><code>env</code></td><td>OS 字符串数组，可选</td><td>它的环境变量，<code>NAME=value</code> 形式的条目；仅当 handler 要求时提供。</td></tr></tbody></table><p>请求的结果是一个动作，由其 <code>action</code> 字段指明：</p><table tabindex="0"><thead><tr><th><code>action</code></th><th>字段</th><th>catter 的行为</th></tr></thead><tbody><tr><td><code>skip</code></td><td></td><td>原样运行命令。</td></tr><tr><td><code>drop</code></td><td></td><td>不运行命令：它以 0 退出。</td></tr><tr><td><code>abort</code></td><td><code>reason</code>：字符串</td><td>结束会话（见下文），并报告原因。</td></tr><tr><td><code>modify</code></td><td><code>args</code>，以及可选的 <code>executable</code>、<code>cwd</code>、<code>env</code></td><td>用这些字段代替命令自己的值运行命令；省略的字段沿用命令原有的值。</td></tr></tbody></table><h3 id="error、exit-和-finish" tabindex="-1"><code>error</code>、<code>exit</code> 和 <code>finish</code> <a class="header-anchor" href="#error、exit-和-finish" aria-label="Permalink to &quot;`error`、`exit` 和 `finish`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>消息</th><th>字段</th></tr></thead><tbody><tr><td><code>error</code></td><td><code>id</code>、<code>parent</code>（可选）、<code>message</code>：catter 未能捕获该命令的原因。</td></tr><tr><td><code>exit</code></td><td><code>id</code>、<code>code</code>：它的退出码，<code>duration</code>：从该 handler 对命令做出决定（对只观察的 handler 而言，是收到通知）到它退出所经过的微秒数，链上排在它之后的 handler 做决定的时间也算在内。</td></tr><tr><td><code>finish</code></td><td><code>code</code>：构建的退出码。结果为 <code>null</code>。</td></tr></tbody></table><h2 id="字符串与数字" tabindex="-1">字符串与数字 <a class="header-anchor" href="#字符串与数字" aria-label="Permalink to &quot;字符串与数字&quot;">​</a></h2><ul><li><strong>OS 字符串。</strong> 参数、路径或环境变量条目的字节是合法的 UTF-8 时，它是一个 JSON 字符串，否则是 <code>{&quot;base64&quot;: &quot;&lt;the bytes in base64&gt;&quot;}</code>：在 Linux 和 macOS 上，它们是字节，不一定是 UTF-8。handler 把这样的值按收到时的样子交回，或者用同样的方式构造一个。</li><li>其他字符串都是合法的 Unicode。JSON 文本不带字节序标记（BOM），任何对象都不会重复同一个键。</li><li>缺省的可选字段可以省略，也可以为 <code>null</code>。</li><li>版本 1 的每个整数都小于 2<sup>53</sup>，JavaScript 数值可以精确表示。</li></ul><h2 id="错误" tabindex="-1">错误 <a class="header-anchor" href="#错误" aria-label="Permalink to &quot;错误&quot;">​</a></h2><p>handler 无法应答某个请求时，以 JSON-RPC 错误应答；catter 报告的就是其中的 <code>message</code>。handler 以错误或 <code>abort</code> 应答、停止运行（输出结束）、写出的内容不是对 catter 某个请求的应答，或没有在 <code>--handler-timeout</code> 内应答时，catter 结束会话：正在做决定的命令，以及构建在其后启动的每条命令，都不运行、直接失败；构建结束后，catter 不发送 <code>finish</code> 就结束各个 handler 的输入，打印原因并以退出码 1 退出。</p><p>只观察的 handler 无法应答通知：它出错时就退出，catter 在下一次向它写入时报告这一情况。</p>',25)])])}const m=e(a,[["render",c]]);export{b as __pageData,m as default};
